const std = @import("std");
const zarrow = @import("zarrow");

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const allocator = std.heap.smp_allocator;
    const n: usize = 20_000;
    var b = try zarrow.Int32Builder.init(allocator, n);
    defer b.deinit();
    for (0..n) |i| try b.append(@intCast(i));
    const arr = try b.finish();
    var datum = zarrow.compute.Datum.fromArray(arr);
    defer datum.release();
    const idx = try allocator.alloc(usize, n);
    defer allocator.free(idx);
    for (idx, 0..) |*v, i| v.* = (i * 7919) % n;
    const t0 = std.Io.Timestamp.now(io, .awake);
    var out = try zarrow.compute.datumTake(datum, idx);
    defer out.release();
    const ns: u64 = @intCast(t0.untilNow(io, .awake).toNanoseconds());
    std.debug.print("benchmark=take rows={d} elapsed_ns={d} ns_per_row={d:.2}\n", .{ n, ns, @as(f64, @floatFromInt(ns)) / @as(f64, @floatFromInt(n)) });
}

